using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates whether a configuration key exists and returns its value")]
    public static string LookupConfig(
        [Description("The configuration key to look up (e.g., 'AppName', 'MaxRetries')")] string key)
    {
        var settings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["AppName"] = "ConfigMcpServer",
            ["Version"] = "1.0.0",
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30",
            ["EnableCaching"] = "true",
            ["EnableLogging"] = "true"
        };

        return settings.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", settings.Keys)}";
    }

    [McpServerTool, Description("Returns a summary of all configuration sections")]
    public static string ListConfigSections()
    {
        return """
            Available configuration sections:
            - config://app/settings  : Core application settings (name, version, timeouts)
            - config://app/endpoints : External service endpoint URLs
            """;
    }
}

